package deposit.api;
import deposit.common.Results.*;import deposit.service.*;import java.util.*;import java.util.stream.Stream;import org.neo4j.procedure.*;
public class ResourceAPI extends BaseAPI {
 @Procedure(name="deposit.resource.beginUpload",mode=Mode.WRITE) public Stream<DataRow> beginUpload(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new ResourceService(c).transfer("beginUpload",request),c.meta())));}
 @Procedure(name="deposit.resource.uploadChunk",mode=Mode.WRITE) public Stream<DataRow> uploadChunk(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new ResourceService(c).transfer("uploadChunk",request),c.meta())));}
 @Procedure(name="deposit.resource.finishUpload",mode=Mode.WRITE) public Stream<DataRow> finishUpload(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new ResourceService(c).transfer("finishUpload",request),c.meta())));}
 @Procedure(name="deposit.resource.abortUpload",mode=Mode.WRITE) public Stream<DataRow> abortUpload(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new ResourceService(c).transfer("abortUpload",request),c.meta())));}
 @Procedure(name="deposit.resource.downloadChunk",mode=Mode.WRITE) public Stream<DataRow> downloadChunk(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new ResourceService(c).read(request,true),c.meta())));}
 @Procedure(name="deposit.resource.info",mode=Mode.WRITE) public Stream<DataRow> info(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new ResourceService(c).read(request,false),c.meta())));}
 @Procedure(name="deposit.admin.pruneResources",mode=Mode.WRITE) public Stream<DataRow> pruneResources(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new ResourceService(c).prune(request),c.meta())));}
 @Procedure(name="deposit.admin.pruneResourcesStatus",mode=Mode.WRITE) public Stream<DataRow> pruneResourcesStatus(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new ResourceService(c).status(request),c.meta())));}
 @Procedure(name="deposit.utils.coordinatesToWKT",mode=Mode.READ) public Stream<DataRow> coordinatesToWKT(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new GeometryService(c).convert(request,true),c.meta())));}
 @Procedure(name="deposit.utils.wktToCoordinates",mode=Mode.READ) public Stream<DataRow> wktToCoordinates(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->Stream.of(new DataRow(new GeometryService(c).convert(request,false),c.meta())));}
}
